    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    rays = []
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r][c] != background and grid[r][c] == grid[r + 1][nc]:
                    rays.append((r - 1, c - dc, -dc, grid[r][c]))
                    rays.append((r + 2, nc + dc, dc, grid[r][c]))
    for r, c, dc, color in rays:
        while 0 <= r < h and 0 <= c < w and grid[r][c] == background:
            out[r][c] = color
            r += 1
            c += dc
    return out

